 p.goto(url+'/HONRO.html');p.wait_for_function('document.documentElement.dataset.honroReady');p.evaluate('HonroApp.launch(11)');p.wait_for_function('HonroApp.engine?.b.honroStage===11');p.wait_for_function('HonroAuthoredFarArt.ready(11)');p.evaluate('()=>{while(HonroApp.dialogue)HonroStory.finish(HonroApp);}');p.wait_for_function('HonroApp.canInput()');p.wait_for_timeout(1000)
 p.evaluate('''()=>{const a=HonroApp,s=a.scene,paint=s.render;s.render=function(...args){window.paintCalls++;return paint.apply(this,args);};window.paintCalls=0;window.waitFrames=n=>new Promise(resolve=>{let i=0;function f(){if(++i<n)requestAnimationFrame(f);else resolve();}requestAnimationFrame(f);});window.hash=async()=>{const c=a.scene.canvas,bytes=c.getContext('2d').getImageData(0,0,c.width,c.height).data;return [...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(v=>v.toString(16).padStart(2,'0')).join('');};a.pause();}''')
 p.evaluate('waitFrames(12)');stable=p.evaluate('''async()=>{paintCalls=0;const a=HonroApp,s=a.scene,e=a.engine,before=JSON.stringify(e.b),canvas=s.canvas,original=await hash(),values=[];await waitFrames(30);values.push(await hash());const skipped=paintCalls;s.render(e,0,a.selected,a.power,a.charging,0,true);values.push(await hash());return {skipped,identical:values.every(v=>v===original),before:original,after:values,statePreserved:before===JSON.stringify(e.b),sameCanvas:canvas===s.canvas,frame:!!s._pausedBattleFrame?.stable};}''');checks.append({'name':'retained vs normal render exact pixels','details':stable});assert stable['skipped']==0 and stable['identical'] and stable['statePreserved'] and stable['sameCanvas'] and stable['frame'],stable
 p.screenshot(path=str(OUT/'final-paused-desktop.jpg'),type='jpeg',quality=90)
 resized=[]
 for w,h in [(390,844),(844,390),(1280,800)]:
  p.evaluate('paintCalls=0');p.set_viewport_size({'width':w,'height':h});p.evaluate('waitFrames(10)');r=p.evaluate('''async()=>{const a=HonroApp,s=a.scene,before=await hash(),count=paintCalls,beforePNG=s.canvas.toDataURL(),prior=s.ctx.getImageData(0,0,s.canvas.width,s.canvas.height).data,camera=[s.x,s.y,s.scale],cache=structuredClone(s._cacheStats);s.render(a.engine,0,a.selected,a.power,a.charging,0,true);const after=s.ctx.getImageData(0,0,s.canvas.width,s.canvas.height).data;let max=0,changed=0;for(let i=0;i<prior.length;i++){max=Math.max(max,Math.abs(prior[i]-after[i]));if(prior[i]!==after[i])changed++;}return {beforePNG,afterPNG:s.canvas.toDataURL(),paints:count,identical:before===await hash(),max,changedChannels:changed,camera,afterCamera:[s.x,s.y,s.scale],cache,afterCache:s._cacheStats,pixels:[s.canvas.width,s.canvas.height]};}''');
  for key in ['beforePNG','afterPNG']:(OUT/f'{w}-{key}.png').write_bytes(base64.b64decode(r.pop(key).split(',')[1]))
  print('RESIZE',r,flush=True);assert r['paints']>=1 and r['identical'],r;resized.append({'viewport':[w,h],**r})
