 dpi=p.evaluate('''async()=>{const a=HonroApp,s=a.scene,before=await hash(),paints=paintCalls;s.render(a.engine,0,a.selected,a.power,a.charging,0,true);return {paints,dpr:devicePixelRatio,width:s.canvas.width,exact:before===await hash()};}''');checks.append({'name':'DPR-only change invalidates at existing resolution cap','details':dpi});assert dpi['paints']>=1 and dpi['dpr']==2 and dpi['width']==2176 and dpi['exact'],dpi
